import { useMemo, useState } from "react"
import { toast } from "sonner"

import { useCollection } from "@/lib/mini/store"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"

import { matchesText, matchesToken, serializeQuery } from "./query"
import { QueryTokens } from "./query-tokens"
import type { Query, QueryKey } from "./types"

type Recipe = {
  id: string
  name: string
  cuisine: string
  course: string
  diets: string[]
  time: number
  rating: number
  ingredients: string[]
}

type RecentSearch = { id: string; query: string; at: number }

type Preview = "live" | "empty" | "loading" | "error"

const PREVIEWS: Preview[] = ["live", "empty", "loading", "error"]
const MAX_RECENT = 8

const SEED: Recipe[] = [
  { id: "r01", name: "Green curry with tofu", cuisine: "thai", course: "main", diets: ["vegan", "vegetarian"], time: 35, rating: 4.5, ingredients: ["tofu", "coconut milk", "basil", "lime"] },
  { id: "r02", name: "Pad see ew", cuisine: "thai", course: "main", diets: [], time: 25, rating: 4, ingredients: ["rice noodles", "garlic", "egg"] },
  { id: "r03", name: "Mango sticky rice", cuisine: "thai", course: "dessert", diets: ["vegetarian", "gluten-free"], time: 40, rating: 4.5, ingredients: ["rice", "coconut milk", "mango"] },
  { id: "r04", name: "Tom kha soup", cuisine: "thai", course: "starter", diets: ["gluten-free"], time: 20, rating: 4, ingredients: ["coconut milk", "lime", "mushroom"] },
  { id: "r05", name: "Margherita flatbread", cuisine: "italian", course: "main", diets: ["vegetarian"], time: 30, rating: 4, ingredients: ["basil", "tomato", "mozzarella"] },
  { id: "r06", name: "Slow lemon risotto", cuisine: "italian", course: "main", diets: ["vegetarian", "gluten-free"], time: 55, rating: 4.5, ingredients: ["rice", "lemon", "parmesan"] },
  { id: "r07", name: "Almond biscotti", cuisine: "italian", course: "snack", diets: ["vegetarian"], time: 75, rating: 3.5, ingredients: ["almond", "egg", "flour"] },
  { id: "r08", name: "White bean bruschetta", cuisine: "italian", course: "starter", diets: ["vegan", "vegetarian"], time: 15, rating: 4, ingredients: ["white beans", "garlic", "basil"] },
  { id: "r09", name: "Black bean tacos", cuisine: "mexican", course: "main", diets: ["vegan", "vegetarian"], time: 25, rating: 4.5, ingredients: ["black beans", "lime", "corn tortillas"] },
  { id: "r10", name: "Chicken tinga bowls", cuisine: "mexican", course: "main", diets: ["gluten-free"], time: 45, rating: 4, ingredients: ["chicken", "chipotle", "rice"] },
  { id: "r11", name: "Churros with chocolate", cuisine: "mexican", course: "dessert", diets: ["vegetarian"], time: 50, rating: 5, ingredients: ["flour", "cinnamon", "chocolate"] },
  { id: "r12", name: "Guacamole and chips", cuisine: "mexican", course: "snack", diets: ["vegan", "vegetarian", "gluten-free"], time: 10, rating: 4.5, ingredients: ["avocado", "lime", "corn tortillas"] },
  { id: "r13", name: "Chana masala", cuisine: "indian", course: "main", diets: ["vegan", "vegetarian", "gluten-free"], time: 40, rating: 4.5, ingredients: ["chickpeas", "tomato", "garlic"] },
  { id: "r14", name: "Palak paneer", cuisine: "indian", course: "main", diets: ["vegetarian", "gluten-free"], time: 35, rating: 4, ingredients: ["spinach", "paneer", "garlic"] },
  { id: "r15", name: "Onion bhaji", cuisine: "indian", course: "starter", diets: ["vegan", "vegetarian"], time: 30, rating: 3.5, ingredients: ["onion", "chickpea flour"] },
  { id: "r16", name: "Cardamom rice pudding", cuisine: "indian", course: "dessert", diets: ["vegetarian", "gluten-free"], time: 70, rating: 4, ingredients: ["rice", "cardamom", "milk"] },
  { id: "r17", name: "Miso soup with greens", cuisine: "japanese", course: "starter", diets: ["vegan", "vegetarian"], time: 12, rating: 4, ingredients: ["miso", "tofu", "spinach"] },
  { id: "r18", name: "Salmon rice bowls", cuisine: "japanese", course: "main", diets: ["gluten-free"], time: 30, rating: 4.5, ingredients: ["salmon", "rice", "cucumber"] },
  { id: "r19", name: "Slow-braised pork belly", cuisine: "japanese", course: "main", diets: [], time: 150, rating: 5, ingredients: ["pork belly", "ginger", "soy sauce"] },
  { id: "r20", name: "Sesame snack balls", cuisine: "japanese", course: "snack", diets: ["vegan", "vegetarian"], time: 20, rating: 3, ingredients: ["sesame", "rice", "sugar"] },
]

const SEED_RECENT: RecentSearch[] = [
  { id: "recent-1", query: "cuisine:thai time:<30", at: 2 },
  { id: "recent-2", query: "course:dessert -diet:vegan", at: 1 },
]

const KEYS: QueryKey[] = [
  { key: "cuisine", type: "choice", hint: "thai", values: ["thai", "italian", "mexican", "indian", "japanese"] },
  { key: "course", type: "choice", hint: "main", values: ["starter", "main", "dessert", "snack"] },
  { key: "diet", type: "choice", hint: "vegan", values: ["vegan", "vegetarian", "gluten-free"] },
  { key: "time", type: "number", hint: "<30", values: ["<15", "<30", "<60", ">60"] },
  { key: "rating", type: "number", hint: ">=4", values: [">=4", ">=4.5", "<4"] },
  { key: "ingredient", type: "text", hint: "basil", values: ["basil", "coconut milk", "garlic", "lime", "rice", "tofu"] },
]

const FIELDS: Record<string, (recipe: Recipe) => string | number | string[]> = {
  cuisine: (recipe) => recipe.cuisine,
  course: (recipe) => recipe.course,
  diet: (recipe) => recipe.diets,
  time: (recipe) => recipe.time,
  rating: (recipe) => recipe.rating,
  ingredient: (recipe) => recipe.ingredients,
}

const matches = (recipe: Recipe, query: Query) =>
  query.tokens.every((token) => matchesToken(token, FIELDS[token.key]?.(recipe))) &&
  matchesText(query.text, recipe.name, ...recipe.ingredients)

const HINTS = [
  "/ focus the search",
  "type a key, then : for its values",
  "Space or Enter turn key:value into a chip",
  "-key:value excludes, time:<30 compares",
  "Backspace in an empty box selects, then removes the last chip",
  "click a chip to edit it",
  "Esc closes the list",
]

export default function Demo() {
  const recipes = useCollection<Recipe>("query-tokens-demo", SEED)
  const recents = useCollection<RecentSearch>("query-tokens-demo-recent", SEED_RECENT)
  const [preview, setPreview] = useState<Preview>("live")
  const [query, setQuery] = useState<Query | undefined>(undefined)

  const status = preview === "live" ? recipes.status : preview === "empty" ? "ready" : preview
  const items = useMemo(() => (preview === "empty" ? [] : recipes.items), [preview, recipes.items])
  const shown = useMemo(
    () => (query ? items.filter((recipe) => matches(recipe, query)) : items),
    [items, query]
  )

  const recentQueries = useMemo(
    () => [...recents.items].sort((a, b) => b.at - a.at).map((recent) => recent.query),
    [recents.items]
  )

  const record = (submitted: Query) => {
    const serialized = serializeQuery(submitted)
    const existing = recents.items.find((recent) => recent.query === serialized)
    const write = existing
      ? recents.update(existing.id, { at: Date.now() })
      : recents.add({ id: `recent-${Date.now()}`, query: serialized, at: Date.now() })
    const stale = [...recents.items]
      .sort((a, b) => b.at - a.at)
      .slice(MAX_RECENT - 1)
      .filter((recent) => recent.id !== existing?.id)
    write
      .then(() => Promise.all(stale.map((recent) => recents.remove(recent.id))))
      .catch(() => toast.error("Could not save the recent search"))
  }

  const restoreSamples = () => {
    setPreview("live")
    void recipes.replaceAll(SEED)
  }

  return (
    <div className="flex h-full min-h-0 flex-col gap-3 p-4">
      <div className="flex flex-wrap items-center gap-2">
        <span className="text-xs text-muted-foreground">State preview (demo only)</span>
        <div role="group" aria-label="State preview" className="flex gap-1">
          {PREVIEWS.map((name) => (
            <Button
              key={name}
              size="xs"
              variant={preview === name ? "default" : "outline"}
              aria-pressed={preview === name}
              onClick={() => setPreview(name)}
              className="capitalize"
            >
              {name}
            </Button>
          ))}
        </div>
      </div>

      <QueryTokens
        keys={KEYS}
        urlParam="q"
        aria-label="Search recipes"
        placeholder="Search recipes, or filter with key:value"
        onChange={setQuery}
        onSubmit={record}
        recent={recentQueries}
        status={status}
        error={new Error("Could not read the recipe collection (simulated).")}
        onRetry={() => setPreview("live")}
        resultCount={shown.length}
        emptyTitle="No recipes yet"
        emptyAction={
          <Button size="sm" variant="outline" onClick={restoreSamples}>
            Restore sample recipes
          </Button>
        }
        boxClassName="lg:grow-0 lg:basis-[57%]"
        toolbar={
          <span className="text-xs text-muted-foreground" aria-live="polite">
            {status === "ready" ? `${shown.length} of ${items.length} recipes` : ""}
          </span>
        }
      >
        <ul role="list" className="overflow-hidden rounded-lg border">
          {shown.map((recipe) => (
            <li
              key={recipe.id}
              className="flex flex-wrap items-center gap-x-3 gap-y-1 border-b px-3 py-2 text-sm last:border-b-0"
            >
              <span data-mini="title" className="min-w-40 flex-1 font-medium">
                {recipe.name}
              </span>
              <span className="flex flex-wrap gap-1">
                <Badge variant="secondary">{recipe.cuisine}</Badge>
                <Badge variant="outline">{recipe.course}</Badge>
                {recipe.diets.map((diet) => (
                  <Badge key={diet} variant="outline" className="text-muted-foreground">
                    {diet}
                  </Badge>
                ))}
              </span>
              <span
                data-mini="cell"
                className="w-28 shrink-0 text-right text-xs text-muted-foreground tabular-nums"
              >
                {recipe.time} min · {recipe.rating.toFixed(1)}
              </span>
            </li>
          ))}
        </ul>
      </QueryTokens>

      <p className="text-xs text-muted-foreground">{HINTS.join(" · ")}</p>
    </div>
  )
}

import {
  useId,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
} from "react"
import { useHotkeys } from "react-hotkeys-hook"
import { SearchIcon, XIcon } from "lucide-react"

import { EmptyState, ErrorState, LoadingState } from "@/components/mini/states"
import { Button } from "@/components/ui/button"
import { Kbd } from "@/components/ui/kbd"
import { cn } from "@/lib/utils"

import {
  EMPTY_QUERY,
  draftText,
  parseDraft,
  parseQuery,
  replaceLastWord,
  serializeQuery,
  serializeText,
  serializeToken,
  typingWord,
} from "./query"
import { flatten, suggest, type Suggestion } from "./suggestions"
import { optionDomId, SuggestionPopover } from "./suggestion-popover"
import { TokenChip } from "./token-chip"
import type { Query, QueryKey } from "./types"
import { useQueryState } from "./use-query-state"

export type QueryTokensProps = {
  keys: QueryKey[]
  value?: Query
  defaultValue?: Query
  onChange?: (query: Query) => void
  onSubmit?: (query: Query) => void
  urlParam?: string
  recent?: string[]
  status?: "loading" | "ready" | "error"
  error?: Error
  onRetry?: () => void
  resultCount?: number
  emptyTitle?: string
  emptyAction?: ReactNode
  placeholder?: string
  autoFocus?: boolean
  boxClassName?: string
  toolbar?: ReactNode
  "aria-label"?: string
  children?: ReactNode
}

/**
 * Search box whose `key:value` words become removable chips, with a popover of keys, values and
 * recent searches. Free words stay as plain text. The parsed query is reported through `onChange`
 * as `{ tokens, text }`; the block takes data as props and never reads the store. `/` focuses the
 * box when focus is on the page body or inside the block. Results go in `children`, and the block
 * shows its Loading, Error and no-results states there.
 */
export function QueryTokens({
  keys,
  value,
  defaultValue,
  onChange,
  onSubmit,
  urlParam,
  recent = [],
  status = "ready",
  error,
  onRetry,
  resultCount,
  emptyTitle = "Nothing here yet",
  emptyAction,
  placeholder = "Search, or filter with key:value",
  autoFocus = false,
  boxClassName,
  toolbar,
  "aria-label": ariaLabel = "Search",
  children,
}: QueryTokensProps) {
  const uid = useId()
  const listId = `${uid}-suggestions`
  const rootRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const [query, setQuery] = useQueryState({ value, defaultValue, onChange, urlParam, keys })
  const [draft, setDraft] = useState(() => serializeText(query.text))
  const [syncedText, setSyncedText] = useState(query.text)
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(-1)
  const [selected, setSelected] = useState<number | null>(null)

  // an outside change to the text (saved view, URL, clear) replaces what the input shows
  if (query.text !== syncedText) {
    setSyncedText(query.text)
    setDraft(serializeText(query.text))
  }

  const keyNames = useMemo(() => keys.map((k) => k.key), [keys])
  const disabled = status !== "ready"
  const list = suggest({
    word: typingWord(draft),
    keys,
    recent,
    draftEmpty: draft.trim() === "",
  })
  const options = flatten(list)
  const showPopover = open && !disabled && (options.length > 0 || list.hint !== undefined)
  const expanded = showPopover && options.length > 0
  const activeIndex = active < options.length ? active : -1

  const focusInput = () => inputRef.current?.focus()

  const commit = (submit: boolean) => {
    const { tokens, rest } = parseDraft(draft, { keys: keyNames, final: true })
    const next: Query = { tokens: [...query.tokens, ...tokens], text: draftText(rest) }
    setDraft(serializeText(next.text))
    if (tokens.length > 0 || next.text !== query.text) setQuery(next)
    if (submit && (next.tokens.length > 0 || next.text)) onSubmit?.(next)
  }

  const typeInto = (next: string) => {
    setSelected(null)
    setActive(-1)
    setOpen(true)
    const { tokens, rest } = parseDraft(next, { keys: keyNames })
    if (tokens.length === 0) return setDraft(next)
    setDraft(rest)
    setQuery({ tokens: [...query.tokens, ...tokens], text: query.text })
  }

  const removeChip = (index: number) => {
    setSelected(null)
    setQuery({ ...query, tokens: query.tokens.filter((_, i) => i !== index) })
    focusInput()
  }

  const editChip = (index: number) => {
    const word = serializeToken(query.tokens[index])
    setSelected(null)
    setQuery({ ...query, tokens: query.tokens.filter((_, i) => i !== index) })
    setDraft(draft && !/\s$/.test(draft) ? `${draft} ${word}` : draft + word)
    setOpen(true)
    focusInput()
  }

  const clear = () => {
    setSelected(null)
    setDraft("")
    setQuery(EMPTY_QUERY)
    setOpen(true)
    focusInput()
  }

  const choose = (item: Suggestion) => {
    setActive(-1)
    if (item.kind === "key") {
      setDraft(replaceLastWord(draft, item.word))
    } else if (item.kind === "value") {
      typeInto(`${replaceLastWord(draft, item.word)} `)
    } else if (item.kind === "recent") {
      const next = parseQuery(item.query, { keys: keyNames })
      setDraft(serializeText(next.text))
      setQuery(next)
      setOpen(false)
      onSubmit?.(next)
    } else {
      commit(true)
      setOpen(false)
    }
    focusInput()
  }

  const onKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing) return
    const input = event.currentTarget
    const lastChip = query.tokens.length - 1
    switch (event.key) {
      case "ArrowDown":
        event.preventDefault()
        if (!open) setOpen(true)
        else if (options.length > 0) setActive(Math.min(options.length - 1, activeIndex + 1))
        break
      case "ArrowUp":
        event.preventDefault()
        if (options.length > 0) setActive(Math.max(-1, activeIndex - 1))
        break
      case "Enter":
        event.preventDefault()
        if (selected !== null) editChip(selected)
        else if (expanded && activeIndex >= 0) choose(options[activeIndex])
        else {
          commit(true)
          setOpen(false)
        }
        break
      case "Escape":
        if (selected !== null) {
          event.preventDefault()
          setSelected(null)
        } else if (showPopover) {
          event.preventDefault()
          setOpen(false)
        } else input.blur()
        break
      case "Backspace":
        if (draft === "" && lastChip >= 0) {
          event.preventDefault()
          if (selected === null) setSelected(lastChip)
          else removeChip(selected)
        }
        break
      case "Delete":
        if (selected !== null) {
          event.preventDefault()
          removeChip(selected)
        }
        break
      case "ArrowLeft":
        if (lastChip >= 0 && input.selectionStart === 0 && input.selectionEnd === 0) {
          event.preventDefault()
          setSelected(selected === null ? lastChip : Math.max(0, selected - 1))
        }
        break
      case "ArrowRight":
        if (selected !== null) {
          event.preventDefault()
          setSelected(selected < lastChip ? selected + 1 : null)
        }
        break
    }
  }

  useHotkeys(
    "slash",
    (event) => {
      const target = event.target
      const inScope =
        target === document.body ||
        target === document.documentElement ||
        (target instanceof Node && rootRef.current?.contains(target) === true)
      if (!inScope) return
      event.preventDefault()
      focusInput()
    },
    { enabled: !disabled }
  )

  const searching = query.tokens.length > 0 || query.text !== ""
  let results: ReactNode = children
  if (status === "loading") results = <LoadingState label="Loading results" />
  else if (status === "error") {
    results = <ErrorState error={error ?? new Error("Could not load the results.")} onRetry={onRetry} />
  } else if (resultCount === 0) {
    results = searching ? (
      <EmptyState
        title="No results match this search"
        description={`Nothing matches ${serializeQuery(query)}. Edit the search or clear it.`}
        action={
          <Button size="sm" variant="outline" onClick={clear}>
            Clear search
          </Button>
        }
      />
    ) : (
      <EmptyState title={emptyTitle} action={emptyAction} />
    )
  }

  const selectedToken = selected !== null ? query.tokens[selected] : undefined

  return (
    <div ref={rootRef} className="flex min-h-0 flex-col gap-3">
      <div className="flex flex-wrap items-center gap-3">
        <div className={cn("relative min-w-0 grow basis-72", boxClassName)}>
          <div
            role="search"
            aria-label={ariaLabel}
            onMouseDown={(event) => {
              if (disabled || (event.target as Element).closest("input")) return
              event.preventDefault()
              focusInput()
            }}
            className={cn(
              "group flex min-h-9 w-full flex-wrap items-center gap-1.5 rounded-lg border border-input bg-background px-2.5 py-1 text-sm transition-colors focus-within:border-ring focus-within:ring-3 focus-within:ring-ring/50",
              disabled && "opacity-60"
            )}
          >
            <SearchIcon className="size-4 shrink-0 text-muted-foreground" aria-hidden />
            {query.tokens.map((token, index) => (
              <TokenChip
                key={`${index}:${serializeToken(token)}`}
                token={token}
                selected={selected === index}
                disabled={disabled}
                onRemove={() => removeChip(index)}
                onEdit={() => editChip(index)}
              />
            ))}
            <input
              ref={inputRef}
              type="text"
              role="combobox"
              aria-label={ariaLabel}
              aria-autocomplete="list"
              aria-haspopup="listbox"
              aria-expanded={expanded}
              aria-controls={expanded ? listId : undefined}
              aria-activedescendant={expanded && activeIndex >= 0 ? optionDomId(listId, activeIndex) : undefined}
              autoComplete="off"
              spellCheck={false}
              autoFocus={autoFocus}
              disabled={disabled}
              value={draft}
              placeholder={query.tokens.length > 0 ? "" : disabled ? "Loading…" : placeholder}
              onChange={(event) => typeInto(event.target.value)}
              onKeyDown={onKeyDown}
              onFocus={() => setOpen(true)}
              onBlur={() => {
                setOpen(false)
                setSelected(null)
                if (draft !== serializeText(query.text)) commit(false)
              }}
              className="min-w-24 flex-1 bg-transparent py-0.5 outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed"
            />
            {searching || draft ? (
              <button
                type="button"
                aria-label="Clear search"
                disabled={disabled}
                onClick={clear}
                className="inline-flex size-6 shrink-0 items-center justify-center rounded-md text-muted-foreground outline-none hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60"
              >
                <XIcon className="size-3.5" aria-hidden />
              </button>
            ) : (
              <Kbd className="group-focus-within:hidden" aria-hidden>
                /
              </Kbd>
            )}
          </div>
          {showPopover ? (
            <SuggestionPopover
              listId={listId}
              sections={list.sections}
              hint={list.hint}
              activeIndex={activeIndex}
              onActivate={setActive}
              onChoose={choose}
            />
          ) : null}
          <span role="status" className="sr-only">
            {selectedToken
              ? `${selectedToken.key} ${selectedToken.value} selected. Press Backspace to remove or Enter to edit.`
              : ""}
          </span>
        </div>
        {toolbar}
      </div>
      {results ? <div className="min-h-0 flex-1">{results}</div> : null}
    </div>
  )
}

import type { Query, QueryToken, TokenOp } from "./types"

export const EMPTY_QUERY: Query = { tokens: [], text: "" }

type Word = { raw: string; start: number; open: boolean }

type ParseOptions = { keys?: string[] }

const HEAD = /^(-?)([A-Za-z_][A-Za-z0-9_.]*):(>=|<=|>|<)?/
const OPS: Record<string, TokenOp> = { ">": "gt", ">=": "gte", "<": "lt", "<=": "lte" }
const SYMBOLS: Record<TokenOp, string> = { eq: "", gt: ">", gte: ">=", lt: "<", lte: "<=" }

/** Splits on whitespace outside double quotes. An unterminated quote runs to the end and marks the word open. */
function lex(input: string): Word[] {
  const words: Word[] = []
  let i = 0
  while (i < input.length) {
    if (/\s/.test(input[i])) {
      i++
      continue
    }
    const start = i
    let open = false
    while (i < input.length) {
      const c = input[i]
      if (open) {
        if (c === "\\" && (input[i + 1] === '"' || input[i + 1] === "\\")) i += 2
        else {
          if (c === '"') open = false
          i++
        }
      } else if (/\s/.test(c)) break
      else {
        if (c === '"') open = true
        i++
      }
    }
    words.push({ raw: input.slice(start, i), start, open })
  }
  return words
}

/** Removes quotes and unescapes `\"` and `\\` inside them. */
function decode(raw: string): string {
  let out = ""
  let open = false
  for (let i = 0; i < raw.length; i++) {
    const c = raw[i]
    if (open) {
      if (c === "\\" && (raw[i + 1] === '"' || raw[i + 1] === "\\")) {
        out += raw[i + 1]
        i++
      } else if (c === '"') open = false
      else out += c
    } else if (c === '"') open = true
    else out += c
  }
  return out
}

function toToken(raw: string, keys?: string[]): QueryToken | null {
  const head = HEAD.exec(raw)
  if (!head) return null
  const rest = raw.slice(head[0].length)
  if (rest === "") return null
  let key = head[2]
  if (keys) {
    const known = keys.find((k) => k.toLowerCase() === key.toLowerCase())
    if (known === undefined) return null
    key = known
  }
  return { key, op: head[3] ? OPS[head[3]] : "eq", value: decode(rest), negated: head[1] === "-" }
}

/** Splits `input` into chips (words that are `key:value`, `-key:value` or `key:<n`) and free text. */
export function parseQuery(input: string, options: ParseOptions = {}): Query {
  const tokens: QueryToken[] = []
  const text: string[] = []
  for (const { raw } of lex(input)) {
    const token = toToken(raw, options.keys)
    if (token) tokens.push(token)
    else text.push(decode(raw))
  }
  return { tokens, text: text.join(" ") }
}

function quoteIf(value: string, needsQuote: boolean): string {
  return needsQuote ? `"${value.replace(/[\\"]/g, "\\$&")}"` : value
}

export function serializeToken(token: QueryToken): string {
  const value = quoteIf(token.value, token.value === "" || /[\s"\\]|^[<>]/.test(token.value))
  return `${token.negated ? "-" : ""}${token.key}:${SYMBOLS[token.op]}${value}`
}

/** Free text as the input shows it: words that would read as a chip or break the quoting are quoted. */
export function serializeText(text: string): string {
  return text
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => {
      const head = HEAD.exec(word)
      const lookalike = head !== null && word.length > head[0].length
      return quoteIf(word, lookalike || /["\\]/.test(word))
    })
    .join(" ")
}

/** Chips first, then the free text; `parseQuery` of the result gives the same query back. */
export function serializeQuery(query: Query): string {
  return [...query.tokens.map(serializeToken), serializeText(query.text)].filter(Boolean).join(" ")
}

/**
 * Reads what the input holds. Finished `key:value` words become chips; the word still being
 * typed (no whitespace after it yet) stays in `rest` unless `final` is set.
 */
export function parseDraft(
  draft: string,
  options: ParseOptions & { final?: boolean } = {}
): { tokens: QueryToken[]; rest: string } {
  const words = lex(draft)
  const last = words[words.length - 1]
  const typing = !options.final && last !== undefined && (last.open || !/\s$/.test(draft))
  const tokens: QueryToken[] = []
  const kept: string[] = []
  words.forEach((word, index) => {
    if (typing && index === words.length - 1) return kept.push(word.raw)
    const token = toToken(word.raw, options.keys)
    if (token) tokens.push(token)
    else kept.push(word.raw)
  })
  const trailing = !typing && kept.length > 0 && /\s$/.test(draft)
  return { tokens, rest: kept.join(" ") + (trailing ? " " : "") }
}

/** The free text a draft holds, decoded the way `parseQuery` would. */
export function draftText(draft: string): string {
  return lex(draft)
    .map((word) => decode(word.raw))
    .join(" ")
}

/** The raw word still being typed, or "" when the draft is empty or ends in whitespace. */
export function typingWord(draft: string): string {
  const last = lex(draft).pop()
  return last && (last.open || !/\s$/.test(draft)) ? last.raw : ""
}

/** Swaps the word being typed for `replacement`, or appends it when the draft ends in whitespace. */
export function replaceLastWord(draft: string, replacement: string): string {
  const last = lex(draft).pop()
  if (!last || (!last.open && /\s$/.test(draft))) return draft + replacement
  return draft.slice(0, last.start) + replacement
}

export function opLabel(token: QueryToken): string {
  if (token.op === "eq") return token.negated ? "is not" : "is"
  return `${token.negated ? "not " : ""}${SYMBOLS[token.op]}`
}

export function describeToken(token: QueryToken): string {
  return `${token.key} ${opLabel(token)} ${token.value}`
}

const numeric = (value: string | number): number | null => {
  if (typeof value === "string" && value.trim() === "") return null
  const n = Number(value)
  return Number.isFinite(n) ? n : null
}

function sameValue(actual: string | number, wanted: string): boolean {
  const a = numeric(actual)
  const b = numeric(wanted)
  if (a !== null && b !== null) return a === b
  return String(actual).toLowerCase() === wanted.toLowerCase()
}

/**
 * Whether a record's value for `token.key` passes the chip. A list matches when any entry does.
 * A comparison against a non-number never matches; a negated chip inverts the result, so a missing value passes it.
 */
export function matchesToken(
  token: QueryToken,
  actual: string | number | readonly (string | number)[] | undefined
): boolean {
  const values = actual === undefined ? [] : typeof actual === "object" ? actual : [actual]
  const wanted = numeric(token.value)
  const hit = values.some((value) => {
    if (token.op === "eq") return sameValue(value, token.value)
    const n = numeric(value)
    if (n === null || wanted === null) return false
    if (token.op === "gt") return n > wanted
    if (token.op === "gte") return n >= wanted
    if (token.op === "lt") return n < wanted
    return n <= wanted
  })
  return token.negated ? !hit : hit
}

/** True when every word of `text` appears in one of `fields`, ignoring case. */
export function matchesText(text: string, ...fields: string[]): boolean {
  const haystack = fields.join(" ").toLowerCase()
  return text
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean)
    .every((word) => haystack.includes(word))
}

/** `href` with `param` set to the query, or removed when it is empty. Only the search part changes; the hash is kept. */
export function searchWithQuery(href: string, param: string, query: Query): string {
  const url = new URL(href)
  const serialized = serializeQuery(query)
  if (serialized) url.searchParams.set(param, serialized)
  else url.searchParams.delete(param)
  return url.toString()
}

export function queryFromSearch(search: string, param: string, options: ParseOptions = {}): Query | null {
  const value = new URLSearchParams(search).get(param)
  return value === null ? null : parseQuery(value, options)
}

import { useEffect } from "react"

import { cn } from "@/lib/utils"

import type { Suggestion, SuggestionSection } from "./suggestions"

export const optionDomId = (listId: string, index: number) => `${listId}-option-${index}`

/**
 * Listbox under the box. It never takes focus: the input owns it through `aria-activedescendant`,
 * and a press on it is kept from blurring the input. With no options it shows only the hint.
 */
export function SuggestionPopover({
  listId,
  sections,
  hint,
  activeIndex,
  onActivate,
  onChoose,
}: {
  listId: string
  sections: SuggestionSection[]
  hint?: string
  activeIndex: number
  onActivate: (index: number) => void
  onChoose: (item: Suggestion) => void
}) {
  useEffect(() => {
    if (activeIndex < 0) return
    document.getElementById(optionDomId(listId, activeIndex))?.scrollIntoView({ block: "nearest" })
  }, [activeIndex, listId])

  let index = -1
  return (
    <div
      onMouseDown={(event) => event.preventDefault()}
      className="absolute inset-x-0 top-full z-30 mt-1 max-h-72 overflow-y-auto rounded-lg border bg-popover p-1 text-sm text-popover-foreground shadow-md"
    >
      {sections.length > 0 ? (
        <div role="listbox" id={listId} aria-label="Suggestions">
          {sections.map((section) => (
            <div key={section.id} role="group" aria-labelledby={`${listId}-${section.id}`}>
              <div
                id={`${listId}-${section.id}`}
                className="px-2 pt-2 pb-1 text-[0.7rem] font-medium tracking-wide text-muted-foreground uppercase"
              >
                {section.label}
              </div>
              {section.items.map((item) => {
                const own = ++index
                return (
                  <div
                    key={`${item.kind}:${item.label}`}
                    role="option"
                    id={optionDomId(listId, own)}
                    aria-selected={own === activeIndex}
                    onMouseMove={() => own !== activeIndex && onActivate(own)}
                    onClick={() => onChoose(item)}
                    className={cn(
                      "flex cursor-default items-center justify-between gap-3 rounded-md px-2 py-1.5",
                      "aria-selected:bg-accent aria-selected:text-accent-foreground"
                    )}
                  >
                    <span className="truncate font-[family-name:var(--mini-font-data)]">{item.label}</span>
                    {item.kind === "key" && item.hint ? (
                      <span className="shrink-0 text-xs text-muted-foreground">{item.hint}</span>
                    ) : null}
                  </div>
                )
              })}
            </div>
          ))}
        </div>
      ) : null}
      {hint ? (
        <p role="status" className="px-2 py-1.5 text-xs text-muted-foreground">
          {hint}
        </p>
      ) : null}
    </div>
  )
}

import type { QueryKey } from "./types"

export type Suggestion =
  | { kind: "key"; label: string; hint?: string; word: string }
  | { kind: "value"; label: string; word: string }
  | { kind: "recent"; label: string; query: string }
  | { kind: "text"; label: string; word: string }

export type SuggestionSection = { id: string; label: string; items: Suggestion[] }

/** `hint` is a line of guidance shown when the section list cannot say what to type next. */
export type SuggestionList = { sections: SuggestionSection[]; hint?: string }

const TYPE_LABELS: Record<QueryKey["type"], string> = { choice: "Choice", number: "Number", text: "Text" }
const MAX_RECENT = 5
const KEY_WORD = /^(-?)([A-Za-z_][A-Za-z0-9_.]*):([\s\S]*)$/

/**
 * What the popover offers for the word being typed. A known `key:` switches to that key's values;
 * anything else lists keys (recent searches first when the whole draft is empty) and, once something
 * is typed, a plain text search row.
 */
export function suggest(input: {
  word: string
  keys: QueryKey[]
  recent: string[]
  draftEmpty: boolean
}): SuggestionList {
  const { word, keys, recent, draftEmpty } = input

  const head = KEY_WORD.exec(word)
  const def = head ? keys.find((k) => k.key.toLowerCase() === head[2].toLowerCase()) : undefined
  if (head && def) {
    const partial = head[3].replace(/^"/, "").toLowerCase()
    const items: Suggestion[] = (def.values ?? [])
      .filter((value) => value.toLowerCase().includes(partial))
      .map((value) => ({
        kind: "value",
        label: value,
        word: `${head[1]}${def.key}:${/\s/.test(value) ? `"${value}"` : value}`,
      }))
    if (items.length > 0) {
      return { sections: [{ id: "values", label: `Values for ${def.key}`, items }] }
    }
    const hint =
      def.type === "choice"
        ? "No matching value"
        : def.type === "number"
          ? "Type a number, optionally after <, >, <= or >=, then press Space or Enter"
          : "Type a value, then press Space or Enter"
    return { sections: [], hint }
  }

  const sections: SuggestionSection[] = []
  if (word === "" && draftEmpty && recent.length > 0) {
    sections.push({
      id: "recent",
      label: "Recent searches",
      items: recent.slice(0, MAX_RECENT).map((query) => ({ kind: "recent", label: query, query })),
    })
  }

  const negated = word.startsWith("-")
  const term = word.slice(negated ? 1 : 0).toLowerCase()
  const matching = keys
    .filter((k) => k.key.toLowerCase().includes(term))
    .sort((a, b) => Number(b.key.toLowerCase().startsWith(term)) - Number(a.key.toLowerCase().startsWith(term)))
  const byType = new Map<QueryKey["type"], QueryKey[]>()
  for (const k of matching) byType.set(k.type, [...(byType.get(k.type) ?? []), k])
  for (const [type, group] of byType) {
    sections.push({
      id: type,
      label: TYPE_LABELS[type],
      items: group.map((k) => ({
        kind: "key",
        label: k.key,
        hint: k.hint,
        word: `${negated ? "-" : ""}${k.key}:`,
      })),
    })
  }

  if (word !== "") {
    sections.push({
      id: "raw",
      label: "Text search",
      items: [{ kind: "text", label: `"${word}"`, word }],
    })
  }
  return { sections }
}

export function flatten(list: SuggestionList): Suggestion[] {
  return list.sections.flatMap((section) => section.items)
}

