/**
 * One `key:value` filter as a removable pill. Clicking the text asks the box to move it back
 * into the input for editing; `selected` marks the chip that Backspace or Delete will remove.
 */
export function TokenChip({
  token,
  selected = false,
  disabled = false,
  onRemove,
  onEdit,
}: {
  token: QueryToken
  selected?: boolean
  disabled?: boolean
  onRemove: () => void
  onEdit: () => void
}) {
  const description = describeToken(token)
  return (
    <span
      role="group"
      aria-label={description}
      data-selected={selected || undefined}
      className={cn(
        "inline-flex h-6 max-w-full items-center rounded-md border bg-muted text-xs",
        selected && "border-(--mini-accent) bg-(--mini-accent-soft) ring-2 ring-ring/50"
      )}
    >
      <span
        title={disabled ? undefined : "Click to edit"}
        onClick={disabled ? undefined : onEdit}
        className={cn(
          "flex min-w-0 items-center gap-1 pl-2",
          !disabled && "cursor-text",
          selected ? "text-foreground" : "text-muted-foreground"
        )}
      >
        <span className="shrink-0">{token.key}</span>
        <span className="shrink-0">{opLabel(token)}</span>
        <span className="max-w-48 truncate font-medium text-foreground">{token.value}</span>
      </span>
      <button
        type="button"
        aria-label={`Remove ${description}`}
        disabled={disabled}
        onClick={onRemove}
        className="ml-0.5 mr-0.5 inline-flex size-5 shrink-0 items-center justify-center rounded-sm text-muted-foreground outline-none hover:bg-background hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/60 disabled:pointer-events-none"
      >
        <XIcon className="size-3" aria-hidden />
      </button>
    </span>
  )
}

export type TokenOp = "eq" | "gt" | "gte" | "lt" | "lte"

export type QueryToken = {
  key: string
  op: TokenOp
  value: string
  negated: boolean
}

/** `text` is the free words joined by single spaces. */
export type Query = { tokens: QueryToken[]; text: string }

export type QueryKey = {
  key: string
  type: "choice" | "number" | "text"
  hint?: string
  values?: string[]
}

import { useEffect, useEffectEvent, useMemo, useState } from "react"

import { EMPTY_QUERY, queryFromSearch, searchWithQuery } from "./query"
import type { Query, QueryKey } from "./types"

function readUrl(param: string | undefined, keys: string[]): Query | null {
  if (!param || typeof window === "undefined") return null
  return queryFromSearch(window.location.search, param, { keys })
}

/**
 * The query as state that follows `value` when the host passes one and is held locally otherwise.
 * With `urlParam` it reads that search param once on mount, reports it through `onChange` so the
 * host sees it, and rewrites the param on every change with `history.replaceState`, touching only
 * the search part so a hash route survives.
 */
export function useQueryState({
  value,
  defaultValue,
  onChange,
  urlParam,
  keys,
}: {
  value?: Query
  defaultValue?: Query
  onChange?: (query: Query) => void
  urlParam?: string
  keys: QueryKey[]
}): [Query, (next: Query) => void] {
  const names = useMemo(() => keys.map((k) => k.key), [keys])
  const controlled = value !== undefined
  const [inner, setInner] = useState<Query>(
    () => readUrl(urlParam, names) ?? defaultValue ?? EMPTY_QUERY
  )

  const reportUrl = useEffectEvent(() => {
    const fromUrl = readUrl(urlParam, names)
    if (fromUrl) onChange?.(fromUrl)
  })
  useEffect(() => reportUrl(), [])

  const set = (next: Query) => {
    if (!controlled) setInner(next)
    onChange?.(next)
    if (!urlParam) return
    try {
      window.history.replaceState(window.history.state, "", searchWithQuery(window.location.href, urlParam, next))
    } catch {
      // some sandboxed frames refuse replaceState; the query still works without the address
    }
  }
  return [controlled ? value : inner, set]
}
